const STORAGE_KEY = 'oro_grafici_live_db_v6';
const SETTINGS_KEY = 'oro_grafici_live_settings_v6';
const OZT_TO_GRAMS = 31.1034768;
const canvas = document.getElementById('chart');
const ctx = canvas.getContext('2d');
const mini = document.getElementById('miniChart');
const mctx = mini.getContext('2d');
let db = loadDb();
let currentKey = 'oggi';
let autoTimer = null;

const labelMap = { oggi:'Oggi', settimana:'Ultima Settimana', mese:'Ultimo Mese', tre_mesi:'Ultimi 3 Mesi', sei_mesi:'Ultimi 6 Mesi', anno:'Ultimo Anno' };
const windowsMs = { oggi:24*3600e3, settimana:7*24*3600e3, mese:30*24*3600e3, tre_mesi:90*24*3600e3, sei_mesi:182*24*3600e3, anno:365*24*3600e3 };

function clone(x){ return JSON.parse(JSON.stringify(x)); }
function loadDb(){
  try { const saved = localStorage.getItem(STORAGE_KEY); if(saved) return JSON.parse(saved); } catch(e) { console.warn(e); }
  const x = clone(INITIAL_DATA); x.live_samples = x.live_samples || []; return x;
}
function saveDb(){ localStorage.setItem(STORAGE_KEY, JSON.stringify(db)); }
function getSettings(){ try{return JSON.parse(localStorage.getItem(SETTINGS_KEY)||'{}')}catch(e){return {}} }
function saveSettings(s){ localStorage.setItem(SETTINGS_KEY, JSON.stringify(s)); }
function setStatus(msg, cls=''){ const el=document.getElementById('liveStatus'); el.textContent=msg; el.className='status '+cls; }
function eur(v){ return Number(v).toLocaleString('it-IT',{minimumFractionDigits:2,maximumFractionDigits:2}) + ' €'; }
function dateLabel(iso,key){
  const d = new Date(iso);
  if(key==='oggi') return d.toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'});
  if(key==='settimana'||key==='mese') return d.toLocaleDateString('it-IT',{day:'2-digit',month:'2-digit'});
  return d.toLocaleDateString('it-IT',{day:'2-digit',month:'2-digit',year:'2-digit'});
}
function niceTicks(min,max,count=7){ const step=(max-min)/(count-1); return Array.from({length:count},(_,i)=>min+step*i); }
function resizeCanvas(c){
  const ratio = window.devicePixelRatio || 1; const rect = c.getBoundingClientRect();
  c.width = Math.max(400, Math.floor(rect.width * ratio)); c.height = Math.floor((c.id==='chart'?470:58) * ratio);
  const g = c.getContext('2d'); g.setTransform(ratio,0,0,ratio,0,0);
}
function drawGrid(g,w,h,pad,yTicks,xTicks,key,points){
  g.clearRect(0,0,w,h); g.fillStyle='#06261c'; g.fillRect(0,0,w,h); g.strokeStyle='rgba(212,175,55,.14)'; g.lineWidth=1;
  yTicks.forEach(t=>{ const y = pad.top + (pad.max-t)/(pad.max-pad.min)*(h-pad.top-pad.bottom); g.beginPath(); g.moveTo(0,y); g.lineTo(w,y); g.stroke(); });
  xTicks.forEach(i=>{ const x = pad.left + i/Math.max(1,points.length-1)*(w-pad.left-pad.right); g.beginPath(); g.moveTo(x,pad.top); g.lineTo(x,h-pad.bottom); g.stroke(); });
  g.fillStyle='rgba(245,216,126,.92)'; g.font='11px Arial'; g.textAlign='right';
  yTicks.forEach(t=>{ const y = pad.top + (pad.max-t)/(pad.max-pad.min)*(h-pad.top-pad.bottom)+4; g.fillText(eur(t), w-8, y); });
  g.textAlign='center'; g.fillStyle='rgba(245,216,126,.70)';
  xTicks.forEach(i=>{ const x=pad.left+i/Math.max(1,points.length-1)*(w-pad.left-pad.right); if(points[i]) g.fillText(dateLabel(points[i].t,key),x,h-10); });
}
function buildPath(g,points,pad,w,h){ points.forEach((p,i)=>{ const x=pad.left+i/Math.max(1,points.length-1)*(w-pad.left-pad.right); const y=pad.top+(pad.max-p.eur_g)/(pad.max-pad.min)*(h-pad.top-pad.bottom); if(i===0)g.moveTo(x,y); else g.lineTo(x,y); }); }
function recalcSeries(s){
  s.points.sort((a,b)=>new Date(a.t)-new Date(b.t));
  const vals=s.points.map(p=>Number(p.eur_g));
  s.period_high_eur_g = Math.max(...vals); s.period_low_eur_g = Math.min(...vals); s.last_eur_g = vals[vals.length-1];
  s.start = s.points[0]?.t || null; s.end = s.points.at(-1)?.t || null;
  s.cleaned_period_high_eur_g = s.period_high_eur_g; s.cleaned_period_low_eur_g = s.period_low_eur_g;
}
function downsample(points, maxPoints){
  if(points.length <= maxPoints) return points;
  const out=[]; const step=(points.length-1)/(maxPoints-1);
  for(let i=0;i<maxPoints;i++) out.push(points[Math.round(i*step)]);
  return out;
}
function mergePointIntoSeries(key, point){
  const s=db.series[key];
  s.points.push(point);
  const now=new Date(point.t).getTime(); const minT=now-windowsMs[key];
  s.points = s.points.filter(p=>new Date(p.t).getTime()>=minT);
  s.points = downsample(s.points, key==='oggi'||key==='settimana'||key==='mese' ? 600 : 800);
  recalcSeries(s);
}
function addLivePrice(eurGram, source='GoldAPI.io'){
  const point={t:new Date().toISOString(), eur_g:Number(eurGram.toFixed(2)), source};
  db.live_samples = db.live_samples || [];
  db.live_samples.push(point);
  db.live_samples = db.live_samples.filter(p=>new Date(p.t).getTime()>=Date.now()-windowsMs.anno);
  Object.keys(windowsMs).forEach(k=>mergePointIntoSeries(k, {t:point.t, eur_g:point.eur_g}));
  db.last_live_update = point.t; db.last_live_source = source;
  saveDb(); drawMain(currentKey);
  setStatus(`Aggiornato: ${eur(point.eur_g)} alle ${new Date(point.t).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}. Salvato nel browser. Quando vuoi premi “Scarica JSON aggiornato”.`, 'ok');
}
async function caricaCambio(){
  const response = await fetch('https://open.er-api.com/v6/latest/USD');
  if(!response.ok) throw new Error(`Cambio USD/EUR non disponibile: ${response.status}`);
  const data = await response.json();
  const rate = Number(data?.rates?.EUR);
  if(!rate || Number.isNaN(rate)) throw new Error('Risposta cambio senza tasso EUR valido.');
  return rate;
}
async function caricaPrezzoOro(){
  const response = await fetch('https://api.gold-api.com/price/XAU');
  if(!response.ok) throw new Error(`Prezzo oro non disponibile: ${response.status}`);
  const data = await response.json();
  const price = Number(data?.price);
  if(!price || Number.isNaN(price)) throw new Error('Risposta oro senza prezzo XAU valido.');
  return price; // USD per oncia troy
}
function fallbackPrezzo(){
  const last = db?.series?.oggi?.last_eur_g || 125;
  return last + Math.sin(Date.now() / 420000) * 0.25 + (Math.random() - 0.5) * 0.06;
}
async function fetchGoldPrice(){
  try {
    const cambioUsdEur = await caricaCambio();
    const prezzoUsdOncia = await caricaPrezzoOro();
    return prezzoUsdOncia * cambioUsdEur / OZT_TO_GRAMS;
  } catch (error) {
    console.warn('Uso fallback prezzo oro:', error);
    setStatus('API non disponibile: uso fallback temporaneo e salvo comunque il punto.', 'warn');
    return fallbackPrezzo();
  }
}
async function updateNow(){
  try {
    setStatus('Richiesta prezzo oro in corso...', 'warn');
    const price = await fetchGoldPrice();
    addLivePrice(price, 'open.er-api.com + api.gold-api.com');
  } catch(e){
    setStatus('Errore aggiornamento: '+e.message, 'err');
    console.error(e);
  }
}
function drawMain(key){
  resizeCanvas(canvas); resizeCanvas(mini);
  const s=db.series[key]; const pts=s.points; if(!pts?.length) return;
  const W=canvas.clientWidth, H=470; const values=pts.map(p=>p.eur_g); let min=Math.min(...values), max=Math.max(...values);
  const margin=(max-min)*0.08 || 1; min=Math.min(min,s.period_low_eur_g)-margin; max=Math.max(max,s.period_high_eur_g)+margin;
  const pad={left:5,right:72,top:18,bottom:42,min,max}; const yTicks=niceTicks(min,max,8);
  const xTicks=[0,Math.floor(pts.length*.16),Math.floor(pts.length*.32),Math.floor(pts.length*.48),Math.floor(pts.length*.64),Math.floor(pts.length*.80),pts.length-1];
  drawGrid(ctx,W,H,pad,yTicks,xTicks,key,pts);
  ctx.beginPath(); buildPath(ctx,pts,pad,W,H); ctx.lineTo(W-pad.right,H-pad.bottom); ctx.lineTo(pad.left,H-pad.bottom); ctx.closePath();
  const grad=ctx.createLinearGradient(0,pad.top,0,H-pad.bottom); grad.addColorStop(0,'rgba(245,197,66,.34)'); grad.addColorStop(1,'rgba(245,197,66,.05)'); ctx.fillStyle=grad; ctx.fill();
  ctx.beginPath(); buildPath(ctx,pts,pad,W,H); ctx.strokeStyle='#f5c542'; ctx.lineWidth=2.2; ctx.stroke();
  drawMini(key, min, max); updateHeader(key,s);
}
function drawMini(key,min,max){
  const s=db.series[key], pts=s.points, W=mini.clientWidth,H=58,pad={left:0,right:0,top:4,bottom:10,min,max};
  mctx.clearRect(0,0,W,H); mctx.fillStyle='#031b14'; mctx.fillRect(0,0,W,H);
  mctx.beginPath(); buildPath(mctx,pts,pad,W,H); mctx.lineTo(W,H-pad.bottom); mctx.lineTo(0,H-pad.bottom); mctx.closePath();
  mctx.fillStyle='rgba(245,197,66,.22)'; mctx.fill(); mctx.beginPath(); buildPath(mctx,pts,pad,W,H); mctx.strokeStyle='rgba(245,197,66,.9)'; mctx.stroke();
  mctx.fillStyle='rgba(245,197,66,.20)'; mctx.fillRect(0,H-8,W,6);
}
function updateHeader(key,s){
  document.getElementById('title').textContent = s.title.replace(' - ',' in ');
  document.getElementById('lastPrice').textContent = eur(s.last_eur_g);
  const first=s.points[0].eur_g, last=s.last_eur_g, diff=last-first, perc=diff/first*100;
  const c=document.getElementById('change'); c.textContent = `${diff>=0?'▲':'▼'} ${eur(diff)} (${perc.toLocaleString('it-IT',{minimumFractionDigits:2,maximumFractionDigits:2})}%)`; c.className = 'change ' + (diff>=0?'up':'');
  document.getElementById('high').textContent = `${labelMap[key]} Alto: ${eur(s.period_high_eur_g)}`; document.getElementById('low').textContent = `${labelMap[key]} Basso: ${eur(s.period_low_eur_g)}`;
  document.querySelectorAll('#periodButtons button[data-key]').forEach(b=>b.classList.toggle('active', b.dataset.key===key && !(key==='oggi' && b.textContent.includes('tempo'))));
}
function exportJson(){
  const blob = new Blob([JSON.stringify(db,null,2)], {type:'application/json'}); const a=document.createElement('a');
  a.href=URL.createObjectURL(blob); const stamp = new Date().toISOString().slice(0,19).replaceAll(':','-');
  a.download=`data_oro_aggiornato_${stamp}.json`; a.click(); URL.revokeObjectURL(a.href);
}
function toggleAuto(){
  const btn=document.getElementById('btnAuto');
  if(autoTimer){ clearInterval(autoTimer); autoTimer=null; btn.textContent='Auto: OFF'; setStatus('Aggiornamento automatico fermato.','warn'); return; }
  const min=Number(document.getElementById('intervalMin').value); autoTimer=setInterval(updateNow, min*60*1000); btn.textContent='Auto: ON'; updateNow();
}

document.getElementById('periodButtons').addEventListener('click',e=>{ const k=e.target.dataset.key; if(k){ currentKey=k; drawMain(k); } });
document.getElementById('btnUpdateNow').addEventListener('click', updateNow);
document.getElementById('btnExport').addEventListener('click', exportJson);
document.getElementById('btnAuto').addEventListener('click', toggleAuto);
document.getElementById('intervalMin').addEventListener('change',()=>{ const s=getSettings(); s.intervalMin=document.getElementById('intervalMin').value; saveSettings(s); setStatus('Intervallo salvato nel browser.','ok'); });
document.getElementById('btnResetLocal').addEventListener('click',()=>{ if(confirm('Vuoi cancellare gli aggiornamenti live salvati nel browser e tornare ai dati iniziali?')){ localStorage.removeItem(STORAGE_KEY); db=loadDb(); drawMain(currentKey); setStatus('Dati locali cancellati: ripartito dal JSON iniziale.','warn'); } });
window.addEventListener('resize',()=>drawMain(currentKey));
const settings=getSettings(); if(settings.intervalMin) document.getElementById('intervalMin').value=settings.intervalMin;
drawMain(currentKey);
